# Test hypothesis: copy patterns between divided regions based on border count and orientation

def predict_region_copy(grid):
    h = len(grid)
    w = len(grid[0])
    bg_val = 3
    border_val = 4

    # Find borders
    horz_border_rows = [r for r in range(h) if all(grid[r][c] == border_val for c in range(w))]
    vert_border_cols = [c for c in range(w) if all(grid[r][c] == border_val for r in range(h))]

    print(f"Horizontal border rows: {horz_border_rows}")
    print(f"Vertical border cols: {vert_border_cols}")

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    if not horz_border_rows and not vert_border_cols:
        # No borders: apply dist-5 propagation
        def apply_dist5_in_direction(grid_2d, direction='horizontal'):
            res = [[v for v in row] for row in grid_2d]

            if direction == 'horizontal':
                for r in range(len(res)):
                    row = res[r]
                    seeds = [(c, v) for c, v in enumerate(row) if v != border_val and v != bg_val]
                    for sc, sv in seeds:
                        for dc in [-5, 5]:
                            pos = sc + dc
                            if 0 <= pos < len(res[r]):
                                res[r][pos] = sv
            else:  # vertical
                for c in range(w):
                    col_seeds = [(r, v) for r, v in enumerate([res[r][c] for r in range(h)]) 
                                 if v != border_val and v != bg_val]
                    for sr, sv in col_seeds:
                        for dr in [-5, 5]:
                            nr = sr + dr
                            if 0 <= nr < h:
                                res[nr][c] = sv

            return res

        return apply_dist5_in_direction(result, 'both')

    elif len(horz_border_rows) == 1 and not vert_border_cols:
        # Single horizontal border: copy ABOVE to BELOW
        br = horz_border_rows[0]
        above = grid[:br]
        below_start = br + 1
        below_end = br + len(above)

        for i in range(len(above)):
            result[br + 1 + i] = list(above[i])

        print(f"Single horiz border at {br}: copying region 0-{br-1} to region {br+1}-{br+len(above)}")
        return result

    elif len(vert_border_cols) == 1 and not horz_border_rows:
        # Single vertical border: copy LEFT to RIGHT
        bc = vert_border_cols[0]
        left = [row[:bc] for row in grid]
        right_start = bc + 1
        right_end = bc + 1 + len(left[0])

        for r in range(len(grid)):
            for c in range(len(left[0])):
                result[r][bc + 1 + c] = left[r][c]

        print(f"Single vert border at {bc}: copying left region to right region")
        return result

    else:
        # Multiple borders: ??? Maybe dist-5 propagation only
        print("Multiple borders: applying dist-5 propagation")
        return apply_dist5_in_direction(result, 'both')

