def backward_trace_dist5(row, bg_val):
    """Try to find source values that would produce this via dist-5"""
    w = len(row)
    sources = list(row)  # Start with copy

    # For each non-bg value, it might have been propagated FROM another position
    changed = True
    while changed:
        changed = False
        new_sources = list(sources)

        for c in range(w):
            v = sources[c]
            if v != bg_val:
                # Check if this could be a propagated value
                candidates = []
                for dc in [-5, 5]:
                    pc = c + dc
                    if 0 <= pc < w:
                        candidates.append(pc)

                if candidates:
                    # Could any candidate be the original source?
                    best_source = None
                    for pc in candidates:
                        pv = sources[pc]
                        if pv != bg_val:
                            best_source = pc
                            break

                    if best_source is not None:
                        new_sources[c] = sources[best_source]
                        changed = True

        sources = new_sources

    return sources

