h, w = 11, 11
sep_row, sep_col = 5, 5

def build_grid_direct():
    out = [[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if i <= sep_row and j <= sep_col:
                mi, mj = i, j
            elif i > sep_row and j <= sep_col:
                mi, mj = i - (sep_row + 1), j
            elif i <= sep_row and j > sep_col:
                mi, mj = i, j - (sep_col + 1)
            else:
                mi, mj = i - (sep_row + 1), j - (sep_col + 1)
            out[i][j] = test_in[mi][mj]
    return out

